function:ruhvi-mobile_DO_NOT_DELETE/src/screens/ChatRoomScreen.tsx:supabase
      .channel(`chat_messages_${id}`, {
        config: {
          broadcast: { ack: true, self: false },
        },
      })
      .on(
        'broadcast',
        { event: 'new_message' },
        (payload: any) => {
          if (payload?.payload) {
            const incoming = payload.payload as ChatMessage;
            setMessages((prev) => {
              if (prev.some((m) => m.id === incoming.id)) return prev;
              return [incoming, ...prev];
            });
            markAsRead();
          }
        }
      )
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'chat_messages', filter: `conversation_id=eq.${id}` },
        async (payload) => {
          // Fetch full message with attachments, reply_to & read receipts
          const { data } = await supabase
            .from('chat_messages')
            .select(`
              *,
              sender:sender_id (
                id,
                full_name,
                email,
                department
              ),
              reply_to:reply_to_id (
                id,
                text_content,
                message_type,
                sender:sender_id (
                  id,
                  full_name,
                  email
                )
              ),
              chat_attachments (*),
              chat_entity_references (*),
              chat_message_reads (
                user_id,
                read_at
              ),
              chat_message_reactions (
                id,
                message_id,
                user_id,
                emoji,
                created_at,
                user:user_id (
                  id,
                  full_name,
                  email
                )
              )
            `)
            .eq('id', payload.new.id)
            .single();

          if (data) {
            setMessages((prev) => {
              if (prev.some(m => m.id === data.id)) return prev;
              return [data as ChatMessage, ...prev];
            });
            markAsRead();
          }
        }
      )
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'chat_messages', filter: `conversation_id=eq.${id}` },
        () => {
          fetchMessages(false);
        }
      )
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'chat_message_reads' },
        () => {
          // When someone reads a message, refresh read receipts live
          fetchMessages(false);
        }
      )
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'chat_message_reactions' },
        () => {
          // Sync reactions live across all devices
          fetchMessages(false);
        }
      )
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'chat_conversations', filter: `id=eq.${id}` },
        () => {
          // Sync pinned message, group name, avatar & topic in real time
          fetchConversation();
        }
      )
      .subscribe

